{"path":"/private/tmp/claude-501/-Users-mihaiperdum-Projects/8508a6a6-9485-42a2-8f18-a56770b707c0/scratchpad/loop12/split/expensesplitter/models.py","content":""""Data models for the expense splitter."""
from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Optional


@dataclass
class Expense:
    """A single expense within a group."""
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])
    payer: str = ""
    amount: Decimal = Decimal("0")
    description: Optional[str] = None
    participants: list[str] = field(default_factory=list)
    shares: dict[str, Decimal] = field(default_factory=dict)  # member -> share (for exact-share splits)

    def to_dict(self) -> dict:
        d = {
            "id": self.id,
            "payer": self.payer,
            "amount": str(self.amount),
            "description": self.description,
            "participants": self.participants,
        }
        if self.shares:
            d["shares"] = {k: str(v) for k, v in self.shares.items()}
        return d

    @classmethod
    def from_dict(cls, data: dict) -> Expense:
        shares = {}
        if "shares" in data and data["shares"]:
            shares = {k: Decimal(v) for k, v in data["shares"].items()}
        return cls(
            id=data.get("id", uuid.uuid4().hex[:8]),
            payer=data["payer"],
            amount=Decimal(data["amount"]),
            description=data.get("description"),
            participants=data.get("participants", []),
            shares=shares,
        )


@dataclass
class Group:
    """A group of members sharing expenses."""
    name: str = ""
    members: list[str] = field(default_factory=list)
    expenses: list[Expense] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "members": self.members,
            "expenses": [e.to_dict() for e in self.expenses],
        }

    @classmethod
    def from_dict(cls, data: dict) -> Group:
        expenses = []
        if "expenses" in data and data["expenses"]:
            expenses = [Expense.from_dict(e) for e in data["expenses"]]
        return cls(
            name=data["name"],
            members=data.get("members", []),
            expenses=expenses,
        )
"}

{"path":"/private/tmp/claude-501/-Users-mihaiperdum-Projects/8508a6a6-9485-42a2-8f18-a56770b707c0/scratchpad/loop12/split/expensesplitter/storage.py","content":""""JSON file persistence for groups."""
from __future__ import annotations

import json
import os
from decimal import Decimal
from typing import Optional

from .models import Group

DEFAULT_DATA_DIR = os.path.expanduser("~/.expensesplitter")
DATA_FILE_NAME = "groups.json"


def _data_path() -> str:
    return os.path.join(DEFAULT_DATA_DIR, DATA_FILE_NAME)


def load_groups(data_dir: Optional[str] = None) -> dict[str, Group]:
    """Load all groups from the JSON file."""
    path = _data_path()
    if data_dir:
        path = os.path.join(data_dir, DATA_FILE_NAME)
    if not os.path.exists(path):
        return {}
    with open(path, "r") as f:
        raw = json.load(f)
    groups: dict[str, Group] = {}
    for name, data in raw.items():
        groups[name] = Group.from_dict(data)
    return groups


def save_groups(groups: dict[str, Group], data_dir: Optional[str] = None) -> None:
    """Save all groups to the JSON file (atomic write)."""
    path = _data_path()
    if data_dir:
        path = os.path.join(data_dir, DATA_FILE_NAME)
    tmp_path = path + ".tmp"
    raw = {name: g.to_dict() for name, g in groups.items()}
    with open(tmp_path, "w") as f:
        json.dump(raw, f, indent=2)
    os.replace(tmp_path, path)


def get_group(name: str, data_dir: Optional[str] = None) -> Optional[Group]:
    groups = load_groups(data_dir=data_dir)
    return groups.get(name)
"}

{"path":"/private/tmp/claude-501/-Users-mihaiperdum-Projects/8508a6a6-9485-42a2-8f18-a56770b707c0/scratchpad/loop12/split/expensesplitter/balances.py","content":""""Compute net balance per member from expense list."""
from __future__ import annotations

from decimal import Decimal

from .models import Expense, Group


def compute_balances(group: Group) -> dict[str, Decimal]:
    """Return {member: net_balance} where positive means they are owed money.

    For each expense:
      - The payer's balance increases by the total amount paid.
      - Each participant's balance decreases by their share.
    """
    balances: dict[str, Decimal] = {m: Decimal("0") for m in group.members}
    for exp in group.expenses:
        # Payer gets credit for full amount
        if exp.payer not in balances:
            balances[exp.payer] = Decimal("0")
        balances[exp.payer] += exp.amount

        # Each participant owes their share
        for member, share in _get_shares(exp).items():
            if member not in balances:
                balances[member] = Decimal("0")
            balances[member] -= share
    return balances


def _get_shares(expense: Expense) -> dict[str, Decimal]:
    """Return the per-member shares for an expense."""
    if expense.shares:
        return expense.shares
    # Equal split among participants
    n = len(expense.participants)
    if n == 0:
        return {}
    share = expense.amount / n
    return {m: share for m in expense.participants}
"}
